<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { Eye,RefreshCw } from 'lucide-vue-next';import { useRouter } from 'vue-router';import AppButton from '@/components/common/AppButton.vue';import AppEmptyState from '@/components/common/AppEmptyState.vue';import AppBreadcrumb from '@/components/layout/AppBreadcrumb.vue';import { receivableService,type ReceivableAging } from '@/services/receivable.service';import { getApiErrorMessage } from '@/utils/error'
const router=useRouter(),asOf=ref(new Date().toISOString().slice(0,10)),data=ref<ReceivableAging|null>(null),loading=ref(false),error=ref(''),search=ref(''),bucket=ref('');const buckets=['current','1-30','31-60','61-90','>90'] as const;const labels={current:'Belum Jatuh Tempo','1-30':'1–30 Hari','31-60':'31–60 Hari','61-90':'61–90 Hari','>90':'> 90 Hari'};const money=(v:string|number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:2}).format(Number(v));const date=(v:string)=>new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date(`${v.slice(0,10)}T00:00:00`));const rows=computed(()=>(data.value?.rows??[]).filter(row=>(!bucket.value||row.aging_bucket===bucket.value)&&(!search.value||`${row.invoice_number} ${row.party_code} ${row.party_name}`.toLowerCase().includes(search.value.toLowerCase()))));const load=async()=>{loading.value=true;error.value='';try{data.value=await receivableService.aging(asOf.value)}catch(e){error.value=getApiErrorMessage(e,'Data piutang gagal dimuat.')}finally{loading.value=false}};onMounted(load)
</script>
<template><div><AppBreadcrumb/><div class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-2xl font-bold">Piutang Usaha</h1><p class="mt-1 text-sm text-slate-500">Outstanding invoice dan umur piutang berdasarkan transaksi posted.</p></div><div class="flex items-end gap-2"><label class="form-label">Posisi per tanggal<input v-model="asOf" type="date" class="field mt-1"/></label><AppButton :icon="RefreshCw" :loading="loading" @click="load">Muat</AppButton></div></div><p v-if="error" class="mb-4 rounded bg-red-50 p-3 text-sm text-red-700">{{error}}</p><section class="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><button v-for="key in buckets" :key="key" class="panel p-4 text-left transition hover:border-blue-300" :class="bucket===key?'ring-2 ring-blue-500':''" @click="bucket=bucket===key?'':key"><span class="text-xs uppercase text-slate-500">{{labels[key]}}</span><b class="mt-2 block text-lg">{{money(data?.buckets[key]??0)}}</b></button></section><section class="panel overflow-hidden"><div class="flex flex-wrap items-center justify-between gap-3 border-b p-4"><input v-model="search" class="field max-w-md" placeholder="Cari invoice atau pelanggan..."/><div class="text-right"><small class="block text-slate-500">Total Piutang</small><b class="text-xl text-blue-700">{{money(data?.total??0)}}</b></div></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-3">Invoice</th><th class="p-3">Pelanggan</th><th class="p-3">Jatuh Tempo</th><th class="p-3 text-right">Awal</th><th class="p-3 text-right">Dibayar/Retur</th><th class="p-3 text-right">Outstanding</th><th class="p-3">Umur</th><th></th></tr></thead><tbody v-if="loading"><tr v-for="i in 5" :key="i"><td colspan="8" class="p-4"><div class="h-5 animate-pulse rounded bg-slate-100"/></td></tr></tbody><tbody v-else class="divide-y"><tr v-for="row in rows" :key="row.id"><td class="p-3 font-mono font-semibold text-blue-700">{{row.invoice_number}}</td><td class="p-3"><b>{{row.party_name}}</b><small class="block text-slate-500">{{row.party_code}}</small></td><td class="p-3">{{date(row.due_date)}}</td><td class="p-3 text-right">{{money(row.original_amount)}}</td><td class="p-3 text-right">{{money(Number(row.paid_amount)+Number(row.returned_amount))}}</td><td class="p-3 text-right font-bold">{{money(row.outstanding_amount)}}</td><td class="p-3"><span class="rounded-full bg-amber-50 px-2 py-1 text-xs font-semibold text-amber-700">{{labels[row.aging_bucket]}}</span></td><td class="p-3"><button class="rounded p-2 hover:bg-slate-100" title="Buka invoice" @click="router.push(`/sales/invoices/${row.id}`)"><Eye class="h-4 w-4"/></button></td></tr></tbody></table></div><AppEmptyState v-if="!loading&&!rows.length&&!error" title="Tidak ada piutang outstanding" description="Tidak ditemukan invoice posted yang masih memiliki saldo pada filter ini."/></section></div></template>
